CREATE OR REPLACE FUNCTION public.mark_ssr_seigniorage_policy_stale()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.description IS DISTINCT FROM OLD.description THEN
    PERFORM public.rebuild_ssr_seigniorage_policy(NEW.recipe_code);
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.morth_pricing_snapshot(p_year text, p_zone text, p_requests jsonb, p_resource_codes text[] DEFAULT '{}'::text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
declare quotes jsonb;resources jsonb;
begin
 if p_year not in ('2026-27','2025-26') or p_year is null then
  raise exception using errcode='22023',message='Select 2026-27 or 2025-26';
 end if;
 if p_zone not in ('zone_1','zone_2','zone_3') or p_zone is null then
  raise exception using errcode='22023',message='Select a valid labour zone';
 end if;
 if jsonb_typeof(p_requests) is distinct from 'array' then
  raise exception using errcode='22023',message='Quote requests must be a JSON array';
 end if;
 if jsonb_array_length(p_requests)>256 or coalesce(cardinality(p_resource_codes),0)>1000 then
  raise exception using errcode='22023',message='Too many pricing identities in one request';
 end if;
 if exists(select 1 from jsonb_array_elements(p_requests) x
   where jsonb_typeof(x) is distinct from 'object' or coalesce(x->>'recipe_code','')=''
   or coalesce(x->>'component','rate') not in
     ('rate','total','hire_total','hire_charge','fuel_charge','crew_charge','capital_cost','tyres_tubes_cost')) then
  raise exception using errcode='22023',message='Invalid quote recipe or rate component';
 end if;
 select coalesce(jsonb_agg(jsonb_build_object(
   'recipe_code',x->>'recipe_code',
   'component',coalesce(x->>'component','rate'),
   'quote',public.sor_resource_quote(x->>'recipe_code',p_year,p_zone,coalesce(x->>'component','rate'),null)
 ) order by n),'[]'::jsonb) into quotes
 from jsonb_array_elements(p_requests) with ordinality q(x,n);
 select coalesce(jsonb_agg(jsonb_build_object(
   'resource_code',a.resource_code,'unit',a.unit,'status',a.status,
   'pricing_records',a.pricing_records
 ) order by a.resource_code),'[]'::jsonb) into resources
 from public.analysis_resource a where a.resource_code=any(coalesce(p_resource_codes,'{}'::text[]));
 return jsonb_build_object('year',p_year,'zone',p_zone,'fetched_at',statement_timestamp(),
   'quotes',quotes,'resources',resources);
end;
$function$

CREATE OR REPLACE FUNCTION public.sor_centering_details_valid(totals jsonb, details jsonb, review_meta jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  status text := review_meta->'cost_review'->>'status';
  h numeric; l numeric; t numeric; adjustment numeric;
  keys text[] := ARRAY['material_hire_charge','labour_charge','centering_charge','rounding_adjustment'];
BEGIN
  IF jsonb_typeof(details) IS DISTINCT FROM 'object'
      OR NOT (details ?& keys) OR details - keys <> '{}'::jsonb
      OR jsonb_typeof(review_meta) IS DISTINCT FROM 'object'
      OR review_meta->>'rate_component' IS DISTINCT FROM 'centering_total'
      OR status IS NULL OR status NOT IN ('priced','deleted','source_clarification') THEN
    RETURN false;
  END IF;
  IF status = 'deleted' THEN
    RETURN coalesce(totals IS NULL AND review_meta->'cost_ready' = 'false'::jsonb
      AND NOT EXISTS (SELECT 1 FROM jsonb_each(details) AS cells WHERE cells.value <> 'null'::jsonb), false);
  END IF;
  IF jsonb_typeof(totals) IS DISTINCT FROM 'number'
      OR EXISTS (SELECT 1 FROM jsonb_each(details) AS cells WHERE jsonb_typeof(cells.value) <> 'number') THEN
    RETURN false;
  END IF;
  h := (details->>'material_hire_charge')::numeric;
  l := (details->>'labour_charge')::numeric;
  t := (details->>'centering_charge')::numeric;
  adjustment := (details->>'rounding_adjustment')::numeric;
  IF h < 0 OR l < 0 OR t < 0 OR t <> totals::text::numeric OR h + l + adjustment <> t THEN
    RETURN false;
  END IF;
  IF status = 'source_clarification' THEN
    RETURN coalesce(review_meta->'cost_ready' = 'false'::jsonb, false);
  END IF;
  IF review_meta->'cost_ready' IS DISTINCT FROM 'true'::jsonb THEN RETURN false; END IF;
  IF adjustment = 0 THEN RETURN true; END IF;
  IF abs(adjustment) > 0.01
      OR review_meta->'rounding_review'->>'status' IS DISTINCT FROM 'approved_published_rounding'
      OR jsonb_typeof(review_meta->'rounding_review'->'difference') IS DISTINCT FROM 'number' THEN
    RETURN false;
  END IF;
  RETURN adjustment = (review_meta->'rounding_review'->>'difference')::numeric;
END;
$function$

CREATE OR REPLACE FUNCTION public.sor_electrical_recipe_rules_valid(spec jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE rule jsonb; c jsonb; r jsonb; keys text[]; seen text[]:=ARRAY[]::text[];
BEGIN
 IF jsonb_typeof(spec) IS DISTINCT FROM 'object' OR spec->'schema_version' IS DISTINCT FROM '1'::jsonb
 OR NOT(spec ?& ARRAY['schema_version','applies_to_recipe_code','rules'])
 OR spec-ARRAY['schema_version','applies_to_recipe_code','rules']<>'{}'::jsonb
 OR coalesce(length(trim(spec->>'applies_to_recipe_code')),0)=0
 OR jsonb_typeof(spec->'rules') IS DISTINCT FROM 'array' OR jsonb_array_length(spec->'rules')=0 THEN RETURN false; END IF;
 FOR rule IN SELECT jsonb_array_elements(spec->'rules') LOOP
  keys:=ARRAY['rule_code','label','operation','value','basis','parameter','condition','base_count','exclusive_group','review_only','review'];
  IF rule->>'operation'='lift_maintenance' THEN keys:=keys||ARRAY['annual_months','higher_floor_monthly_charge']; END IF;
  IF jsonb_typeof(rule) IS DISTINCT FROM 'object' OR NOT(rule ?& keys) OR rule-keys<>'{}'::jsonb
  OR coalesce(rule->>'operation','') NOT IN ('percentage','percentage_each','fixed_each','lift_maintenance')
  OR coalesce(rule->>'basis','') NOT IN ('scheduled_rate','finished_cost_data','reference_lift_cost')
  OR jsonb_typeof(rule->'value') IS DISTINCT FROM 'number' OR (rule->>'value')::numeric=0
  OR jsonb_typeof(rule->'base_count') IS DISTINCT FROM 'number' OR (rule->>'base_count')::numeric<0
  OR jsonb_typeof(rule->'review_only') IS DISTINCT FROM 'boolean'
  OR coalesce(length(trim(rule->>'rule_code')),0)=0 OR coalesce(length(trim(rule->>'label')),0)=0
  OR coalesce(length(trim(rule->>'parameter')),0)=0 OR rule->>'rule_code'=ANY(seen) THEN RETURN false; END IF;
  seen:=array_append(seen,rule->>'rule_code'); c:=rule->'condition'; r:=rule->'review';
  IF jsonb_typeof(c) IS DISTINCT FROM 'object' OR NOT((c ? 'equals' AND c-ARRAY['equals']='{}'::jsonb)
    OR (c ?& ARRAY['equals','floor_minimum','floor_maximum'] AND c-ARRAY['equals','floor_minimum','floor_maximum']='{}'::jsonb)
    OR (c ?& ARRAY['minimum','maximum'] AND c-ARRAY['minimum','maximum']='{}'::jsonb)) THEN RETURN false; END IF;
  IF c ? 'minimum' AND ((c->>'minimum')::numeric<0 OR (c->>'maximum')::numeric<(c->>'minimum')::numeric) THEN RETURN false; END IF;
  IF c ? 'floor_minimum' AND (NOT(c ? 'floor_maximum') OR (c->>'floor_minimum')::numeric<1 OR (c->>'floor_maximum')::numeric<(c->>'floor_minimum')::numeric) THEN RETURN false; END IF;
  IF NOT(r ?& ARRAY['status','reviewer','source_pdf_sha256','source_pdf_page','source_note','reason'])
  OR coalesce(r->>'status','')<>'approved' OR coalesce(r->'reviewer'->>'kind','')<>'ai'
  OR coalesce(length(trim(r->'reviewer'->>'model')),0)=0 OR coalesce(r->>'source_pdf_sha256','')!~'^[0-9a-f]{64}$'
  OR (r->>'source_pdf_page')::integer<1 OR coalesce(length(trim(r->>'source_note')),0)=0
  OR coalesce(length(trim(r->>'reason')),0)=0 THEN RETURN false; END IF;
  IF rule->>'operation'='lift_maintenance' AND (rule->>'basis'<>'reference_lift_cost'
    OR (rule->>'annual_months')::numeric<>12 OR (rule->>'higher_floor_monthly_charge')::numeric<=0) THEN RETURN false; END IF;
 END LOOP;
 RETURN true;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $function$

CREATE OR REPLACE FUNCTION public.sor_electrical_year_review_valid()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE recipe public."SOR_Recipie"; spec jsonb; status text;
BEGIN
 IF new.table_code<>'P03-T04' THEN RETURN new; END IF;
 SELECT * INTO recipe FROM public."SOR_Recipie" WHERE recipe_code=new.recipe_code;
 status:=new.metadata->'cost_review'->>'status'; spec:=recipe.addons->'electrical_rules';
 IF recipe.table_code IS DISTINCT FROM 'P03-T04' OR new.unit IS DISTINCT FROM recipe.unit
 OR new.part_no<>3 OR new.zone IS DISTINCT FROM ''
 OR status IS NULL OR status NOT IN ('priced','formula','source_clarification')
 OR new.metadata->'cost_ready' IS DISTINCT FROM to_jsonb(status IN ('priced','formula')) THEN
 RAISE EXCEPTION 'Electrical year needs the reviewed Recipe, unit and cost status'; END IF;
 IF status IN ('priced','source_clarification') AND (jsonb_typeof(new.rate) IS DISTINCT FROM 'number' OR (new.rate#>>'{}')::numeric<0) THEN
 RAISE EXCEPTION 'Electrical numeric tariff must preserve its source price'; END IF;
 IF new.metadata->'fixed_electrical_item_code' IS DISTINCT FROM 'true'::jsonb
 OR coalesce(new.metadata->>'source_pdf_sha256','')!~'^[0-9a-f]{64}$'
 OR (status IN ('priced','source_clarification') AND
   (new.rate#>>'{}')::numeric IS DISTINCT FROM replace(replace(new.metadata->'price_source_row'->'raw_cells'->>-1,',',''),' ','')::numeric) THEN
 RAISE EXCEPTION 'Electrical tariff must bind its original source price and fixed code'; END IF;
 IF status='formula' AND (new.rate IS NOT NULL OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(spec->'rules') r WHERE r->>'operation'='lift_maintenance')) THEN
 RAISE EXCEPTION 'Formula tariff needs NULL rate and a reviewed pricing formula'; END IF;
 IF spec IS NOT NULL AND (new.metadata->'recipe_addon_review'->>'status' IS DISTINCT FROM 'unchanged'
 OR new.metadata->'recipe_addon_review'->'rule_snapshot' IS DISTINCT FROM spec) THEN
 RAISE EXCEPTION 'Electrical annual rules differ from permanent Recipe'; END IF;
 RETURN new;
END $function$

CREATE OR REPLACE FUNCTION public.sor_fiscal_start(p_year text)
 RETURNS integer
 LANGUAGE plpgsql
 IMMUTABLE STRICT
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE n integer;
BEGIN
 IF p_year !~ '^[0-9]{4}-[0-9]{2}$' THEN RAISE EXCEPTION 'Year must be YYYY-YY'; END IF;
 n:=left(p_year,4)::integer;
 IF n<1900 OR right(p_year,2)::integer<>(n+1)%100 THEN RAISE EXCEPTION 'Invalid financial year'; END IF;
 RETURN n;
END $function$

CREATE OR REPLACE FUNCTION public.sor_morth_analysis_link_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
declare o jsonb;
begin
 if tg_op='UPDATE' and old.rate->>'type'='morth_analysis' and new.rate->>'type' is distinct from 'morth_analysis' then
  raise exception 'Do not discard reviewed MoRTH Rate links during re-extraction; replay the exact-year reviewed manifest';
 end if;
 if new.rate->>'type' is distinct from 'morth_analysis' then return new; end if;
 if not public.sor_morth_analysis_rate_valid(new.rate) then raise exception 'Invalid MoRTH analysis reference'; end if;
 if new.part_no<>2 or new.table_code<>'P02-T03' or new.metadata->'cost_ready' is distinct from 'false'::jsonb
  or new.metadata->'cost_review'->>'status' is distinct from 'analysis_required'
  or new.metadata->'morth_link_review'->'reviewer'->>'kind' is distinct from 'ai'
  or coalesce(new.metadata->'morth_link_review'->'reviewer'->>'model','')=''
  then raise exception 'MoRTH research candidates must retain explicit AI evidence and costing hold'; end if;
 for o in select value from jsonb_array_elements(new.rate->'options') loop
  if not exists(select 1 from public.morth m where m.code=o->>'morth_code'
    and m.source_edition=o->>'source_edition' and m.source_pages=o->'source_pages') then
   raise exception 'Unknown or changed MoRTH key/source evidence: %',o->>'morth_code';
  end if;
 end loop;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.sor_morth_analysis_options(p_recipe_code text, p_year text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
declare resolved jsonb; y public."SOR_Year"; n bigint; options jsonb;
begin
 resolved:=public.sor_resolve_recipe_year(p_recipe_code,p_year);
 if coalesce((resolved->>'requires_review')::boolean,false) then return resolved; end if;
 select count(*) into n from public."SOR_Year" where recipe_code=resolved->>'recipe_code' and year=p_year;
 if n<>1 then return resolved||jsonb_build_object('status',case when n=0 then 'selected_year_rate_missing' else 'annual_scope_review_required' end,'rate',null); end if;
 select * into y from public."SOR_Year" where recipe_code=resolved->>'recipe_code' and year=p_year;
 if y.rate->>'type' is distinct from 'morth_analysis' then return resolved||jsonb_build_object('status','not_morth_analysis_reference','rate',null); end if;
 select coalesce(jsonb_agg(o.value||jsonb_build_object('description',m.description,
  'description_detail',m.description_detail,'project_category',m.project_category,'unit',m.unit,
  'analysis_quantity',m.analysis_quantity,'rate_divisor',m.rate_divisor,'analysis',m.recipe,
  'can_auto_price',false) order by o.n),'[]'::jsonb) into options
 from jsonb_array_elements(y.rate->'options') with ordinality o(value,n)
 join public.morth m on m.code=o.value->>'morth_code';
 return resolved||jsonb_build_object('year',p_year,'year_row_code',y.year_row_code,'unit',y.unit,'status',y.rate->>'status',
  'rate',null,'cost_ready',false,'options',options,'requirements',y.rate->'requirements','reason',y.rate->>'reason',
  'review',y.metadata->'morth_link_review','to_be_printed',y.to_be_printed);
end $function$

CREATE OR REPLACE FUNCTION public.sor_public_health_details_valid(t jsonb, d jsonb, m jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE v jsonb; total numeric:=0;
BEGIN
 IF d IS NULL THEN RETURN true; END IF;
 IF d->'schema_version' IS DISTINCT FROM '1'::jsonb OR d-ARRAY['schema_version','components','total_basis']<>'{}'::jsonb OR jsonb_typeof(d->'components') IS DISTINCT FROM 'object' OR jsonb_typeof(t) IS DISTINCT FROM 'number' THEN RETURN false; END IF;
 IF m->>'item_type'='maintenance_job' THEN
  IF NOT(d->'components' ?& ARRAY['material_charge','labour_machinery_other_charge']) OR (d->'components')-ARRAY['material_charge','labour_machinery_other_charge']<>'{}'::jsonb OR d->>'total_basis'<>'published_total' THEN RETURN false; END IF;
 ELSE
  IF NOT(d->'components' ?& ARRAY['labour_charge','implements_charge']) OR (d->'components')-ARRAY['labour_charge','implements_charge']<>'{}'::jsonb OR d->>'total_basis'<>'component_sum' THEN RETURN false; END IF;
 END IF;
 FOR v IN SELECT value FROM jsonb_each(d->'components') LOOP
  IF jsonb_typeof(v)<>'number' OR (v#>>'{}')::numeric<0 THEN RETURN false; END IF; total:=total+(v#>>'{}')::numeric;
 END LOOP;
 IF total=(t#>>'{}')::numeric THEN RETURN true; END IF;
 -- Retain a misprinted source total only as an explicitly blocked AI review.
 RETURN coalesce(
  m->>'item_type'='maintenance_job'
  AND m->'cost_ready'='false'::jsonb
  AND m->>'rate_status'='source_clarification'
  AND m->'cost_review'->>'status'='source_clarification'
  AND m->'component_review'->>'status'='unresolved_source_arithmetic'
  AND m->'component_review'->'reviewer'->>'kind'='ai'
  AND length(m->'component_review'->>'reason')>0
  AND jsonb_typeof(m->'component_review'->'component_sum')='number'
  AND jsonb_typeof(m->'component_review'->'published_total')='number'
  AND (m->'component_review'->>'component_sum')::numeric=total
  AND (m->'component_review'->>'published_total')::numeric=(t#>>'{}')::numeric,
 false);
EXCEPTION WHEN OTHERS THEN RETURN false;
END $function$

CREATE OR REPLACE FUNCTION public.sor_public_health_recipe_valid()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE c jsonb;
BEGIN
 IF new.part_no<>4 THEN RETURN new; END IF;
 IF new.structure='MATRIX' THEN
  c:=new.metadata->'public_health_cell';
  IF c->'schema_version' IS DISTINCT FROM '1'::jsonb OR c->'column'->>'unit' IS DISTINCT FROM new.unit
   OR NOT(c ?& ARRAY['group','row_axis','column_axis','row','column'])
   OR coalesce(length(c->'row'->>'label'),0)=0 OR coalesce(length(c->'column'->>'label'),0)=0
   OR new.metadata ?| ARRAY['matrix','matrix_cell','parent_recipe_code'] THEN RAISE EXCEPTION 'Independent Part IV matrix coordinate required'; END IF;
 END IF;
 IF jsonb_path_exists(new.metadata,'$.**.rate') OR jsonb_path_exists(new.metadata,'$.**.rate_detailed') OR jsonb_path_exists(new.metadata,'$.**.year') THEN RAISE EXCEPTION 'Annual prices do not belong in Recipe'; END IF;
 RETURN new;
END $function$

CREATE OR REPLACE FUNCTION public.sor_public_health_year_valid()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE r public."SOR_Recipie"; status text; expected jsonb; lead public."SOR_Lead_Rule"; source numeric; raw text;
BEGIN
 IF new.part_no<>4 THEN RETURN new; END IF;
 SELECT * INTO r FROM public."SOR_Recipie" WHERE recipe_code=new.recipe_code;
 status:=new.metadata->'cost_review'->>'status';
 IF r.part_no IS DISTINCT FROM 4 OR new.unit IS DISTINCT FROM r.unit OR new.table_code IS DISTINCT FROM r.table_code OR new.structure IS DISTINCT FROM r.structure OR new.zone IS DISTINCT FROM '' THEN RAISE EXCEPTION 'Wrong Part IV annual definition or unit'; END IF;
 IF status IS NULL OR status NOT IN ('priced','calculated','formula','not_published','reference_required','source_clarification')
 OR new.metadata->'cost_ready' IS DISTINCT FROM to_jsonb(status IN ('priced','calculated','formula'))
 OR coalesce(new.metadata->>'source_pdf_sha256','')!~'^[0-9a-f]{64}$' OR new.metadata->'recipe_review'->'reviewer'->>'kind' IS DISTINCT FROM 'ai' THEN RAISE EXCEPTION 'Annual Part IV requires source and AI review'; END IF;
 IF status IN ('not_published','reference_required','formula') AND new.rate IS NOT NULL THEN RAISE EXCEPTION 'Unpublished/reference/formula tariff must not invent a rate'; END IF;
 IF status IN ('priced','calculated') AND (jsonb_typeof(new.rate) IS DISTINCT FROM 'number' OR (new.rate#>>'{}')::numeric<0) THEN RAISE EXCEPTION 'Missing published Part IV tariff'; END IF;
 IF r.addons IS NOT NULL AND (new.metadata->'recipe_addon_review'->>'status' IS DISTINCT FROM 'unchanged' OR new.metadata->'recipe_addon_review'->'rule_snapshot' IS DISTINCT FROM r.addons->'public_health_rules') THEN RAISE EXCEPTION 'Part IV rule changed; AI must review a new definition'; END IF;
 IF new.metadata ? 'lead_rule_code' THEN
  SELECT * INTO lead FROM public."SOR_Lead_Rule" WHERE rule_code=new.metadata->>'lead_rule_code';
  IF lead.rules->>'schema_version' IS DISTINCT FROM '3' OR NOT(lead.rules->'source_recipe_codes' ? new.recipe_code) OR lead.rules->>'quantity_unit' IS DISTINCT FROM new.unit THEN RAISE EXCEPTION 'Wrong pipe rule coordinate or unit'; END IF;
 ELSIF r.lead_applicability='PIPE' THEN RAISE EXCEPTION 'Missing annual PIPE rule'; END IF;
 IF new.rate_detailed IS NOT NULL THEN
  IF new.metadata->>'item_type'='maintenance_job' THEN expected:='[{"key":"material_charge","label":"Material (Rs.)","path":"rate_detailed.components.material_charge"},{"key":"labour_machinery_other_charge","label":"Labour, machinery and other (Rs.)","path":"rate_detailed.components.labour_machinery_other_charge"}]'::jsonb;
  ELSE expected:='[{"key":"labour_charge","label":"Labour (Rs.)","path":"rate_detailed.components.labour_charge"},{"key":"implements_charge","label":"Implements (Rs.)","path":"rate_detailed.components.implements_charge"}]'::jsonb; END IF;
  IF new.to_be_printed->'extra_columns' IS DISTINCT FROM expected THEN RAISE EXCEPTION 'Print the exact Part IV cost breakdown'; END IF;
 END IF;
 IF status='priced' AND new.metadata->'price_token'='null'::jsonb AND new.metadata->'source_correction'='null'::jsonb THEN
  raw:=new.metadata->>'published_rate_text';
  IF raw!~'^[0-9][0-9,]*(\.[0-9]+)?$' THEN RAISE EXCEPTION 'Part IV tariff lacks its numeric source'; END IF;
  source:=replace(raw,',','')::numeric * (new.metadata->>'price_scale')::numeric;
  IF source IS DISTINCT FROM (new.rate#>>'{}')::numeric THEN RAISE EXCEPTION 'Part IV tariff differs from source'; END IF;
 END IF;
 RETURN new;
END $function$

CREATE OR REPLACE FUNCTION public.sor_recipe_fallback_valid(p_code text, p_unit text, r jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE f jsonb; review jsonb; source jsonb; y text; used text[]:=ARRAY[]::text[];
 n integer; prior public."SOR_Recipie"; rates jsonb;
BEGIN
 IF r IS NULL THEN RETURN; END IF;
 IF r->>'schema_version'='3' THEN
  IF r->'schema_version' IS DISTINCT FROM '3'::jsonb OR (SELECT count(*) FROM jsonb_object_keys(r))<>3 OR NOT r ?& ARRAY['schema_version','first_available_year','historical_fallbacks']
  OR public.sor_fiscal_start(r->>'first_available_year') IS NULL THEN RAISE EXCEPTION 'Invalid fallback-only link'; END IF;
 END IF;
 IF NOT r ? 'historical_fallbacks' THEN RETURN; END IF;
 IF jsonb_typeof(r->'historical_fallbacks') IS DISTINCT FROM 'array'
 OR (r->>'schema_version'='3' AND jsonb_array_length(r->'historical_fallbacks')=0) THEN RAISE EXCEPTION 'Invalid historical fallback rules'; END IF;
 FOR f IN SELECT value FROM jsonb_array_elements(r->'historical_fallbacks') LOOP
  IF jsonb_typeof(f) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(f))<>6
  OR NOT f ?& ARRAY['relationship_type','target_recipe_code','years','mode','reason','review']
  OR f->>'relationship_type' IS DISTINCT FROM 'historical_fallback'
  OR coalesce(f->>'mode','') NOT IN('automatic','review_required')
  OR jsonb_typeof(f->'target_recipe_code') IS DISTINCT FROM 'string' OR btrim(f->>'target_recipe_code')=''
  OR f->>'target_recipe_code'=p_code OR jsonb_typeof(f->'reason') IS DISTINCT FROM 'string'
  OR btrim(f->>'reason')='' OR jsonb_typeof(f->'years') IS DISTINCT FROM 'array'
  OR jsonb_array_length(f->'years')=0 THEN RAISE EXCEPTION 'Invalid historical_fallback relationship'; END IF;
  review:=f->'review'; rates:=review->'rate_comparison';
  IF review->>'status' IS DISTINCT FROM 'approved' OR review->'reviewer'->>'kind' IS DISTINCT FROM 'ai'
  OR coalesce(review->'reviewer'->>'model','')='' OR coalesce(review->>'pdf_sha256','')!~'^[0-9a-f]{64}$'
  OR NOT public.sor_fallback_pages_valid(review->'source_pages') OR NOT public.sor_fallback_pages_valid(review->'target_pages')
  THEN RAISE EXCEPTION 'Historical fallback requires AI source approval'; END IF;
  n:=public.sor_fiscal_start(review->>'source_year');
  IF n IS NULL OR (r->>'schema_version'='3' AND review->>'source_year' IS DISTINCT FROM r->>'first_available_year')
  OR jsonb_typeof(review->'comparison') IS DISTINCT FROM 'object'
  OR (SELECT count(*) FROM jsonb_object_keys(review->'comparison'))<>5
  OR NOT (review->'comparison') ?& ARRAY['definition','quantity_basis','scope','variants','addons']
  OR EXISTS(SELECT 1 FROM jsonb_each(review->'comparison') c WHERE c.value->>'status' IS DISTINCT FROM 'checked'
    OR coalesce(btrim(c.value->>'reason'),'')='') THEN RAISE EXCEPTION 'AI must compare complete fallback definitions and quantity/scope'; END IF;
  IF rates->>'year' IS DISTINCT FROM review->>'source_year'
  OR NOT public.sor_fallback_rate_valid(rates->'source_rate') OR NOT public.sor_fallback_rate_valid(rates->'target_rate')
  OR (f->>'mode'='automatic' AND rates->'source_rate' IS DISTINCT FROM rates->'target_rate')
  THEN RAISE EXCEPTION 'Fallback rate comparison needs same-edition rates'; END IF;
  IF jsonb_typeof(review->'historical_sources') IS DISTINCT FROM 'array'
  OR jsonb_array_length(review->'historical_sources')<>jsonb_array_length(f->'years')
  THEN RAISE EXCEPTION 'Each historical fallback year needs original PDF evidence'; END IF;
  FOR y IN SELECT jsonb_array_elements_text(f->'years') LOOP
   IF y=ANY(used) OR public.sor_fiscal_start(y) IS NULL OR public.sor_fiscal_start(y)>=n
   THEN RAISE EXCEPTION 'Historical fallback years must be earlier and nonoverlapping'; END IF;
   used:=array_append(used,y);
   SELECT value INTO source FROM jsonb_array_elements(review->'historical_sources') s
     WHERE s.value->>'year'=y;
   IF NOT FOUND OR (SELECT count(*) FROM jsonb_array_elements(review->'historical_sources') s WHERE s.value->>'year'=y)<>1
   OR coalesce(source->>'pdf_sha256','')!~'^[0-9a-f]{64}$' OR NOT public.sor_fallback_pages_valid(source->'pdf_pages')
   THEN RAISE EXCEPTION 'Each historical fallback year needs original PDF evidence'; END IF;
  END LOOP;
  SELECT * INTO prior FROM public."SOR_Recipie" WHERE recipe_code=f->>'target_recipe_code' FOR KEY SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Missing historical fallback target'; END IF;
  IF f->>'mode'='automatic' AND p_unit IS DISTINCT FROM prior.unit THEN RAISE EXCEPTION 'Automatic fallback requires same quantity basis'; END IF;
 END LOOP;
END $function$

CREATE OR REPLACE FUNCTION public.sor_recipe_relationships_valid()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE v jsonb; a jsonb; target public."SOR_Recipie"; code text;
BEGIN
 SELECT variants,addons INTO v,a FROM public."SOR_Recipie" WHERE recipe_code=new.recipe_code;
 IF v IS NOT NULL THEN
  IF jsonb_typeof(v)<>'object' OR v->>'schema_version'<>'1' OR (v-ARRAY['schema_version','main_recipe_code','axis','value'])<>'{}'::jsonb OR NOT(v ?& ARRAY['main_recipe_code','axis','value']) THEN
   RAISE EXCEPTION 'Invalid one-axis variant relationship'; END IF;
  SELECT * INTO target FROM public."SOR_Recipie" WHERE recipe_code=v->>'main_recipe_code';
  IF target.recipe_code IS NULL OR target.structure<>'ROW' OR target.variants->>'main_recipe_code' IS DISTINCT FROM target.recipe_code OR target.variants->>'axis' IS DISTINCT FROM v->>'axis' THEN
   RAISE EXCEPTION 'Variant main must be an actual row in the same family'; END IF;
 END IF;
 IF a IS NOT NULL THEN
  IF a->>'schema_version'<>'1' OR jsonb_typeof(a)<>'object' THEN RAISE EXCEPTION 'Invalid addon relationship'; END IF;
  IF a ? 'recipe_codes' THEN
   FOR code IN SELECT jsonb_array_elements_text(a->'recipe_codes') LOOP
    SELECT * INTO target FROM public."SOR_Recipie" WHERE recipe_code=code;
    IF target.recipe_code IS NULL OR code=new.recipe_code OR target.metadata->>'item_type' IS DISTINCT FROM 'adjustment' THEN
     RAISE EXCEPTION 'Addon link must reference an adjustment Recipe'; END IF;
   END LOOP;
  ELSIF a ? 'rule' THEN
   IF NOT(a->'rule' ?& ARRAY['applies_to','when','operation','requires','component','basis']) THEN RAISE EXCEPTION 'Incomplete addon rule'; END IF;
   FOR code IN SELECT jsonb_array_elements_text(a->'rule'->'applies_to') UNION ALL SELECT jsonb_array_elements_text(a->'rule'->'requires') LOOP
    IF code=new.recipe_code OR NOT EXISTS(SELECT 1 FROM public."SOR_Recipie" WHERE recipe_code=code) THEN
     RAISE EXCEPTION 'Addon rule target/dependency is absent'; END IF;
   END LOOP;
  ELSIF a ? 'height_rule' THEN
   IF (a-ARRAY['schema_version','height_rule'])<>'{}'::jsonb
      OR NOT public.sor_centering_recipe_addon_valid(a->'height_rule')
      OR a->'height_rule'->>'applies_to_recipe_code' IS DISTINCT FROM new.recipe_code THEN
     RAISE EXCEPTION 'Invalid inline Recipe height addon'; END IF;
   IF NOT EXISTS(SELECT 1 FROM public."SOR_Recipie" r WHERE r.recipe_code=new.recipe_code AND r.table_code='P03-T02' AND r.structure='MATRIX') THEN
     RAISE EXCEPTION 'Height addon belongs to a centering coordinate'; END IF;
  ELSIF a ? 'porcelain_colour_rule' THEN
   IF (a-ARRAY['schema_version','porcelain_colour_rule'])<>'{}'::jsonb
      OR NOT public.sor_plumbing_porcelain_rule_valid(a->'porcelain_colour_rule')
      OR a->'porcelain_colour_rule'->>'applies_to_recipe_code' IS DISTINCT FROM new.recipe_code
      OR NOT EXISTS(SELECT 1 FROM public."SOR_Recipie" r WHERE r.recipe_code=new.recipe_code AND r.table_code='P03-T03' AND r.structure='ROW') THEN
      RAISE EXCEPTION 'Invalid inline Plumbing porcelain addon'; END IF;
  ELSIF a ? 'electrical_rules' THEN
   IF (a-ARRAY['schema_version','electrical_rules'])<>'{}'::jsonb
      OR NOT public.sor_electrical_recipe_rules_valid(a->'electrical_rules')
      OR a->'electrical_rules'->>'applies_to_recipe_code' IS DISTINCT FROM new.recipe_code
      OR NOT EXISTS(SELECT 1 FROM public."SOR_Recipie" r WHERE r.recipe_code=new.recipe_code AND r.table_code='P03-T04' AND r.structure='ROW') THEN
      RAISE EXCEPTION 'Invalid inline Electrical Recipe rules'; END IF;
  ELSIF a ? 'public_health_rules' THEN
   IF (a-ARRAY['schema_version','public_health_rules'])<>'{}'::jsonb
    OR NOT public.sor_public_health_rules_valid(a->'public_health_rules')
    OR a->'public_health_rules'->>'applies_to_recipe_code' IS DISTINCT FROM new.recipe_code
    OR NOT EXISTS(SELECT 1 FROM public."SOR_Recipie" r WHERE r.recipe_code=new.recipe_code AND r.part_no=4) THEN
    RAISE EXCEPTION 'Invalid permanent Public Health application rules'; END IF;
   FOR code IN SELECT x->>'target_recipe_code' FROM jsonb_array_elements(a->'public_health_rules'->'rules') x WHERE x->>'target_recipe_code' IS NOT NULL LOOP
    IF code=new.recipe_code OR NOT EXISTS(SELECT 1 FROM public."SOR_Recipie" r WHERE r.recipe_code=code AND r.part_no=4 AND r.metadata->>'item_type' IN ('adjustment','supply')) THEN
     RAISE EXCEPTION 'Public Health addon target is missing or has the wrong scope'; END IF;
   END LOOP;
  ELSE RAISE EXCEPTION 'Addon needs reviewed Recipe links or an inline rule'; END IF;
 END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.sor_recipe_revision_valid()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE r jsonb; prior public."SOR_Recipie"; source jsonb; source_key text; n integer;
 before_codes jsonb; after_codes jsonb; c text; cardinality_kind text;
BEGIN
 IF TG_OP='DELETE' THEN
  PERFORM pg_advisory_xact_lock(hashtextextended('public.SOR_Recipie.recipe_revision',0));
  IF EXISTS(SELECT 1 FROM public."SOR_Recipie" x WHERE
    public.sor_revision_previous(x.recipe_revision) ? old.recipe_code
    OR (x.recipe_code<>old.recipe_code AND public.sor_revision_replacements(x.recipe_revision,x.recipe_code) ? old.recipe_code)
    OR x.recipe_revision->'historical_fallbacks' @> jsonb_build_array(jsonb_build_object('target_recipe_code',old.recipe_code))) THEN
   RAISE EXCEPTION 'Recipe is referenced by a revision predecessor or replacement group'; END IF;
  RETURN old;
 END IF;
 IF TG_OP='UPDATE' AND new.recipe_revision IS NOT DISTINCT FROM old.recipe_revision THEN RETURN new; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('public.SOR_Recipie.recipe_revision',0));
 PERFORM public.sor_recipe_fallback_valid(new.recipe_code,new.unit,new.recipe_revision);
 r:=public.sor_revision_core(new.recipe_revision);
 IF r IS NULL THEN RETURN new; END IF;
 IF jsonb_typeof(r) IS DISTINCT FROM 'object' OR r->'schema_version' NOT IN ('1'::jsonb,'2'::jsonb)
 OR r->'schema_version' IS NULL THEN RAISE EXCEPTION 'Recipe revision needs reviewed schema 1 or 2'; END IF;
 IF r->>'schema_version'='1' THEN
  IF (SELECT count(*) FROM jsonb_object_keys(r))<>7 OR NOT r ?& ARRAY['schema_version','previous_recipe_code','effective_from_year','change_kind','replacement_mode','reason','review']
   OR jsonb_typeof(r->'previous_recipe_code') IS DISTINCT FROM 'string' THEN RAISE EXCEPTION 'Invalid v1 revision fields'; END IF;
 ELSE
  IF (SELECT count(*) FROM jsonb_object_keys(r))<>8 OR NOT r ?& ARRAY['schema_version','previous_recipe_codes','replacement_recipe_codes','effective_from_year','change_kind','replacement_mode','reason','review']
   OR jsonb_typeof(r->'previous_recipe_codes') IS DISTINCT FROM 'array'
   OR jsonb_typeof(r->'replacement_recipe_codes') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'Invalid v2 revision fields'; END IF;
 END IF;
 before_codes:=public.sor_revision_previous(r); after_codes:=public.sor_revision_replacements(r,new.recipe_code);
 IF jsonb_array_length(before_codes)=0 OR jsonb_array_length(after_codes)=0
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(before_codes||after_codes) x WHERE jsonb_typeof(x) IS DISTINCT FROM 'string' OR btrim(x#>>'{}')='')
 OR (SELECT count(DISTINCT x) FROM jsonb_array_elements(before_codes) x)<>jsonb_array_length(before_codes)
 OR (SELECT count(DISTINCT x) FROM jsonb_array_elements(after_codes) x)<>jsonb_array_length(after_codes)
 OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(before_codes) x WHERE after_codes ? x)
 OR NOT after_codes ? new.recipe_code THEN RAISE EXCEPTION 'Distinct predecessor and replacement codes required'; END IF;
 IF jsonb_array_length(before_codes)=1 AND jsonb_array_length(after_codes)=1 THEN
  IF coalesce(r->>'change_kind','') NOT IN ('definition_change','reference_change') THEN RAISE EXCEPTION 'Invalid one-to-one revision kind'; END IF;
 ELSE
  cardinality_kind:=CASE WHEN jsonb_array_length(before_codes)=1 THEN 'split_definition'
   WHEN jsonb_array_length(after_codes)=1 THEN 'merged_definition' ELSE NULL END;
  IF cardinality_kind IS NULL OR r->>'change_kind' IS DISTINCT FROM cardinality_kind
   OR r->>'replacement_mode' IS DISTINCT FROM 'review_required' THEN
   RAISE EXCEPTION 'Splits and merges require explicit estimate review'; END IF;
 END IF;
 IF coalesce(r->>'replacement_mode','') NOT IN ('automatic','review_required')
 OR jsonb_typeof(r->'reason') IS DISTINCT FROM 'string' OR btrim(r->>'reason')=''
 OR jsonb_typeof(r->'review') IS DISTINCT FROM 'object'
 OR (SELECT count(*) FROM jsonb_object_keys(r->'review'))<>4
 OR NOT (r->'review') ?& ARRAY['status','reviewer','previous_source','replacement_source']
 OR r->'review'->>'status' IS DISTINCT FROM 'approved'
 OR r->'review'->'reviewer'->>'kind' IS DISTINCT FROM 'ai'
 OR coalesce(r->'review'->'reviewer'->>'model','')='' THEN RAISE EXCEPTION 'Explicit AI revision approval required'; END IF;
 n:=public.sor_fiscal_start(r->>'effective_from_year');
 IF n IS NULL THEN RAISE EXCEPTION 'Revision needs a financial year boundary'; END IF;
 FOREACH source_key IN ARRAY ARRAY['previous_source','replacement_source'] LOOP
  source:=r->'review'->source_key;
  IF jsonb_typeof(source) IS DISTINCT FROM 'object'
  OR (SELECT count(*) FROM jsonb_object_keys(source))<>3
  OR NOT source ?& ARRAY['year','pdf_sha256','pdf_pages']
  OR coalesce(source->>'pdf_sha256','')!~'^[0-9a-f]{64}$'
  OR jsonb_typeof(source->'pdf_pages') IS DISTINCT FROM 'array'
  OR jsonb_array_length(source->'pdf_pages')=0 THEN RAISE EXCEPTION 'Revision source needs PDF hash and pages'; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(source->'pdf_pages') p WHERE jsonb_typeof(p) IS DISTINCT FROM 'number' OR p::text !~ '^[1-9][0-9]*$')
  OR (SELECT count(DISTINCT p) FROM jsonb_array_elements(source->'pdf_pages') p)<>jsonb_array_length(source->'pdf_pages')
  OR public.sor_fiscal_start(source->>'year') IS NULL THEN RAISE EXCEPTION 'Invalid revision source pages/year'; END IF;
 END LOOP;
 IF public.sor_fiscal_start(r->'review'->'previous_source'->>'year')>=n
 OR r->'review'->'replacement_source'->>'year' IS DISTINCT FROM r->>'effective_from_year' THEN RAISE EXCEPTION 'Invalid chronological revision boundary'; END IF;
 FOR c IN SELECT jsonb_array_elements_text(before_codes) LOOP
  SELECT * INTO prior FROM public."SOR_Recipie" WHERE recipe_code=c FOR KEY SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Missing predecessor Recipe'; END IF;
  IF r->>'replacement_mode'='automatic' AND new.unit IS DISTINCT FROM prior.unit THEN RAISE EXCEPTION 'Automatic replacement requires the same quantity basis'; END IF;
 END LOOP;
 RETURN new;
END $function$

CREATE OR REPLACE FUNCTION public.sor_recipe_validate_lead_links()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
declare rules jsonb; branch jsonb;
begin
  select lead_applicability into rules from public."SOR_Recipie" where recipe_code=new.recipe_code;
  if rules is null then return null; end if;
  if not public.sor_lead_rules_valid(rules) then
    raise exception 'Lead applicability needs conditional rule schema version 2';
  end if;
  for branch in select value from (
    select jsonb_path_query(rules, '$.components.*.cases[*].then') value
    union all select jsonb_path_query(rules, '$.components.*.otherwise') value
  ) results loop
    if (select count(*)<>count(distinct value->>'recipe_code') from jsonb_array_elements(branch->'terms') value) then
      raise exception 'Duplicate Lead Recipe terms';
    end if;
  end loop;
  if exists (select 1 from public.sor_lead_rule_codes(rules) code
      left join public."SOR_Recipie" target on target.recipe_code=code
      where target.recipe_code is null or target.recipe_code=new.recipe_code
        or target.structure<>'MATRIX'
        or target.metadata->>'item_type' is distinct from 'conveyance_matrix_cell'
        or not (target.metadata ? 'matrix_cell')) then
    raise exception 'Lead applicability must reference existing Conveyance cell Recipes';
  end if;
  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.sor_resolve_recipe_revision(p_recipe_code text, p_year text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE n integer; current_code text; r public."SOR_Recipie"; successor public."SOR_Recipie";
 queue text[]:=ARRAY[p_recipe_code]; path text[]:=ARRAY[]::text[]; blocked text[]:=ARRAY[]::text[];
 selected text[]:=ARRAY[]::text[]; targets text[]; result jsonb;
BEGIN
 n:=public.sor_fiscal_start(p_year);
 IF n IS NULL THEN RAISE EXCEPTION 'Year is required'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public."SOR_Recipie" WHERE recipe_code=p_recipe_code) THEN RAISE EXCEPTION 'Unknown or inaccessible Recipe code'; END IF;
 WHILE cardinality(queue)>0 LOOP
  current_code:=queue[1]; queue:=queue[2:];
  CONTINUE WHEN current_code=ANY(path);
  path:=array_append(path,current_code);
  SELECT * INTO r FROM public."SOR_Recipie" WHERE recipe_code=current_code;
  IF NOT FOUND THEN RAISE EXCEPTION 'Incomplete or inaccessible Recipe lineage'; END IF;
  IF public.sor_revision_core(r.recipe_revision) IS NOT NULL AND public.sor_fiscal_start(r.recipe_revision->>'effective_from_year')>n THEN
   SELECT array_agg(c ORDER BY c) INTO targets FROM jsonb_array_elements_text(public.sor_revision_previous(r.recipe_revision)) c;
   IF r.recipe_revision->>'replacement_mode'='review_required' THEN blocked:=array_append(blocked,current_code); END IF;
   queue:=queue||targets;
  ELSE
   SELECT * INTO successor FROM public."SOR_Recipie" x WHERE public.sor_revision_previous(x.recipe_revision) ? current_code LIMIT 1;
   IF FOUND AND public.sor_fiscal_start(successor.recipe_revision->>'effective_from_year')<=n THEN
    SELECT array_agg(c ORDER BY c) INTO targets FROM jsonb_array_elements_text(public.sor_revision_replacements(successor.recipe_revision,successor.recipe_code)) c;
    IF successor.recipe_revision->>'replacement_mode'='review_required' THEN blocked:=blocked||targets; END IF;
    queue:=queue||targets;
   ELSE selected:=array_append(selected,current_code);
   END IF;
  END IF;
 END LOOP;
 SELECT coalesce(array_agg(DISTINCT c ORDER BY c),ARRAY[]::text[]) INTO selected FROM unnest(selected) c;
 SELECT coalesce(array_agg(DISTINCT c ORDER BY c),ARRAY[]::text[]) INTO blocked FROM unnest(blocked) c;
 RETURN jsonb_build_object('requested_recipe_code',p_recipe_code,'recipe_code',CASE WHEN cardinality(selected)=1 THEN selected[1] ELSE NULL END,
  'recipe_codes',to_jsonb(selected),'year',p_year,'revision_path',to_jsonb(path),
  'requires_review',cardinality(blocked)>0 OR cardinality(selected)<>1,'review_boundaries',to_jsonb(blocked));
END $function$

CREATE OR REPLACE FUNCTION public.sor_resolve_recipe_revision_v1(p_recipe_code text, p_year text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE n integer; current_code text:=p_recipe_code; root_code text; r public."SOR_Recipie";
 successor public."SOR_Recipie"; path text[]; lineage text[]; blocked text[]:=ARRAY[]::text[]; a integer; b integer; i integer;
BEGIN
 n:=public.sor_fiscal_start(p_year);
 IF n IS NULL THEN RAISE EXCEPTION 'Year is required'; END IF;
 SELECT * INTO r FROM public."SOR_Recipie" WHERE recipe_code=current_code;
 IF NOT FOUND THEN RAISE EXCEPTION 'Unknown or inaccessible Recipe code'; END IF;
 LOOP
  EXIT WHEN r.recipe_revision IS NULL;
  current_code:=r.recipe_revision->>'previous_recipe_code';
  SELECT * INTO r FROM public."SOR_Recipie" WHERE recipe_code=current_code;
  IF NOT FOUND THEN RAISE EXCEPTION 'Incomplete or inaccessible Recipe lineage'; END IF;
 END LOOP;
 root_code:=current_code; path:=ARRAY[root_code]; lineage:=path;
 LOOP
  SELECT * INTO successor FROM public."SOR_Recipie" WHERE recipe_revision->>'previous_recipe_code'=r.recipe_code;
  EXIT WHEN NOT FOUND;
  lineage:=array_append(lineage,successor.recipe_code);
  IF public.sor_fiscal_start(successor.recipe_revision->>'effective_from_year')<=n THEN
   current_code:=successor.recipe_code; path:=array_append(path,current_code);
  END IF;
  r:=successor;
 END LOOP;
 a:=least(array_position(lineage,p_recipe_code),array_position(lineage,current_code));
 b:=greatest(array_position(lineage,p_recipe_code),array_position(lineage,current_code));
 IF a<b THEN
  FOR i IN a+1..b LOOP
   SELECT * INTO r FROM public."SOR_Recipie" WHERE recipe_code=lineage[i];
   IF r.recipe_revision->>'replacement_mode'='review_required' THEN blocked:=array_append(blocked,r.recipe_code); END IF;
  END LOOP;
 END IF;
 RETURN jsonb_build_object('requested_recipe_code',p_recipe_code,'recipe_code',current_code,'year',p_year,
 'revision_path',to_jsonb(path),'requires_review',cardinality(blocked)>0,'review_boundaries',to_jsonb(blocked));
END $function$

CREATE OR REPLACE FUNCTION public.sor_resolve_recipe_year(p_recipe_code text, p_year text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE result jsonb; current_code text:=p_recipe_code; visited text[]:=ARRAY[]::text[];
 path jsonb:='[]'::jsonb; f jsonb; step jsonb; links jsonb; code text;
BEGIN
 LOOP
  result:=public.sor_resolve_recipe_revision(current_code,p_year);
  result:=result||jsonb_build_object('requested_recipe_code',p_recipe_code,'fallback_used',jsonb_array_length(path)>0,'fallback_path',path);
  IF (result->>'requires_review')::boolean THEN RETURN result; END IF;
  code:=result->>'recipe_code';
  IF code=ANY(visited) THEN RAISE EXCEPTION 'Historical fallback/revision cycle'; END IF;
  visited:=array_append(visited,code);
  -- Any existing annual row wins, including blank, held and other-zone rows.
  IF EXISTS(SELECT 1 FROM public."SOR_Year" WHERE recipe_code=code AND year=p_year) THEN RETURN result; END IF;
  SELECT recipe_revision->'historical_fallbacks' INTO links FROM public."SOR_Recipie" WHERE recipe_code=code;
  SELECT value INTO f FROM jsonb_array_elements(coalesce(links,'[]'::jsonb)) v WHERE v.value->'years' ? p_year;
  IF NOT FOUND THEN RETURN result; END IF;
  step:=jsonb_build_object('relationship_type','historical_fallback','from_recipe_code',code,'to_recipe_code',f->>'target_recipe_code','year',p_year);
  IF f->>'mode'='review_required' THEN RETURN result||jsonb_build_object('requires_review',true,
   'status','fallback_review_required','fallback_candidate',step); END IF;
  path:=path||jsonb_build_array(step);current_code:=f->>'target_recipe_code';
 END LOOP;
END $function$

CREATE OR REPLACE FUNCTION public.sor_resource_links_valid(x jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE k text;v jsonb;t text;c text;
BEGIN
 IF x IS NULL OR jsonb_typeof(x) NOT IN('object','array') THEN RETURN true; END IF;
 IF jsonb_typeof(x)='array' THEN
  FOR v IN SELECT value FROM jsonb_array_elements(x) LOOP IF NOT public.sor_resource_links_valid(v) THEN RETURN false; END IF; END LOOP;RETURN true;
 END IF;
 FOREACH k IN ARRAY ARRAY['table','source_table','identity_table','rate_table'] LOOP
  t:=x->>k;
  IF t IN('sor_dataset_release','sor_recipe_definition','sor_recipe_observation','sor_adjustment_rule','sor_reviewed_navigation_node','sor_reviewed_navigation_variant','sor_recipe_alias','sor_catalogue','sor_catalogue_item','sor_catalogue_rate','civil','civil_rate','plumbing','plumbing_rate','electrical','electrical_rate','electrical_item_version','material','material_rate','machinery','machinery_rate','labour','labour_rate','material_rate_monthly','material_rate_document','ssr_material_alias','pipe_lead_item','pipe_lead_rate','lead_charge','lead_rate','lead_note','lead_detail_item','lead_detail_year','conveyance_charge','conveyance_rate') THEN RETURN false; END IF;
  c:=coalesce(x->>'recipe_code',x->>'resource_code',x->>'code',x->>'master_code');
  IF t IN('SOR_Recipie','SOR_Year') AND c IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public."SOR_Recipie" WHERE recipe_code=c) THEN RETURN false; END IF;
  IF t='analysis_resource' AND c IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.analysis_resource WHERE resource_code=c) THEN RETURN false; END IF;
 END LOOP;
 IF jsonb_typeof(x->'rate_tables')='array' AND EXISTS(SELECT 1 FROM jsonb_array_elements_text(x->'rate_tables') t(entry) WHERE t.entry NOT IN('SOR_Year','analysis_resource','morth')) THEN RETURN false; END IF;
 FOR k,v IN SELECT * FROM jsonb_each(x) LOOP IF NOT public.sor_resource_links_valid(v) THEN RETURN false; END IF; END LOOP;
 RETURN true;
END $function$

CREATE OR REPLACE FUNCTION public.sor_resource_quote(p_recipe_code text, p_year text, p_zone text DEFAULT NULL::text, p_component text DEFAULT 'rate'::text, p_unit text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE revision jsonb;r public."SOR_Year";n bigint;amount jsonb;detail jsonb;factor numeric:=1;u text;requested text;reference jsonb;result jsonb;
BEGIN
 revision:=public.sor_resolve_recipe_year(p_recipe_code,p_year);
 IF (revision->>'requires_review')::boolean THEN RETURN revision||jsonb_build_object('status',coalesce(revision->>'status','revision_review_required'),'rate',NULL); END IF;
 SELECT count(*) INTO n FROM public."SOR_Year" WHERE recipe_code=revision->>'recipe_code' AND year=p_year;
 IF n<>1 THEN RETURN revision||jsonb_build_object('status',CASE WHEN n=0 THEN 'selected_year_rate_missing' ELSE 'annual_scope_review_required' END,'rate',NULL); END IF;
 SELECT * INTO r FROM public."SOR_Year" WHERE recipe_code=revision->>'recipe_code' AND year=p_year;
 IF r.rate->>'type'='morth_analysis' THEN
  RETURN revision||jsonb_build_object('status','morth_analysis_review_required','rate',NULL,
   'year',p_year,'year_row_code',r.year_row_code,'unit',r.unit,'cost_ready',false,
   'analysis_rate',r.rate,'cost_review',r.metadata->'cost_review','to_be_printed',r.to_be_printed);
 END IF;
 IF r.metadata->>'cost_ready'='false' OR (r.metadata->'cost_review'->>'status' IS NOT NULL AND r.metadata->'cost_review'->>'status' NOT IN('priced','reference_only')) THEN RETURN revision||jsonb_build_object('status','source_review_required','rate',NULL,'cost_review',r.metadata->'cost_review'); END IF;
 reference:=r.metadata->'reference_review';
 IF r.rate IS NULL OR r.rate='null'::jsonb THEN
  IF reference->>'status'='approved' AND r.metadata->'cost_review'->>'status'='reference_only' AND reference->>'rate_basis_factor'='1' AND lower(r.unit)='per hour' AND reference->>'target_recipe_code'<>r.recipe_code THEN
   IF p_zone IS DISTINCT FROM reference->>'selected_zone' THEN RETURN revision||jsonb_build_object('status','pricing_zone_review_required','rate',NULL); END IF;
   IF NOT EXISTS(SELECT 1 FROM public."SOR_Year" y WHERE y.recipe_code=reference->>'target_recipe_code' AND y.year=p_year AND y.effective_from=r.effective_from AND y.table_code='P01-T08') THEN RETURN revision||jsonb_build_object('status','selected_year_reference_missing','rate',NULL); END IF;
   result:=public.sor_resource_quote(reference->>'target_recipe_code',p_year,p_zone,p_component,p_unit);
   RETURN result||jsonb_build_object('requested_recipe_code',p_recipe_code,'recipe_code',r.recipe_code,'price_recipe_code',reference->>'target_recipe_code','to_be_printed',r.to_be_printed);
  END IF;
  RETURN revision||jsonb_build_object('status','rate_unavailable','rate',NULL,'cost_review',r.metadata->'cost_review');
 END IF;
 IF jsonb_typeof(r.rate)='object' THEN
  IF p_zone IS NULL OR p_zone NOT IN('zone_1','zone_2','zone_3') THEN RETURN revision||jsonb_build_object('status','zone_required','rate',NULL); END IF;
  amount:=r.rate->p_zone;detail:=r.rate_detailed->p_zone;
 ELSE
  IF coalesce(r.zone,'')<>'' AND r.zone IS DISTINCT FROM p_zone THEN RETURN revision||jsonb_build_object('status','pricing_zone_review_required','rate',NULL,'required_zone',r.zone); END IF;
  amount:=r.rate;detail:=r.rate_detailed;
 END IF;
 IF p_component NOT IN('rate','total','hire_total') THEN amount:=detail->p_component; END IF;
 IF jsonb_typeof(amount) IS DISTINCT FROM 'number' THEN RETURN revision||jsonb_build_object('status','component_rate_unavailable','rate',NULL,'component',p_component); END IF;
 factor:=public.sor_unit_rate_factor(r.unit,p_unit);
 IF factor IS NULL THEN RETURN revision||jsonb_build_object('status','unit_conversion_review_required','rate',NULL,'source_unit',r.unit,'requested_unit',p_unit); END IF;
 RETURN revision||jsonb_build_object('status','priced','year_row_code',r.year_row_code,'year',p_year,'zone',p_zone,'component',p_component,'source_unit',r.unit,'unit',coalesce(p_unit,r.unit),'conversion_factor',factor,'rate',(amount#>>'{}')::numeric*factor,'rate_detailed',detail,'to_be_printed',r.to_be_printed);
END $function$

CREATE OR REPLACE FUNCTION public.sor_shared_lead_protect_revision()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
 IF tg_op='UPDATE' AND to_jsonb(new) IS DISTINCT FROM to_jsonb(old) THEN
  RAISE EXCEPTION 'Shared lead rule revisions are immutable; publish a new reviewed revision'; END IF;
 IF tg_op='DELETE' AND EXISTS(SELECT 1 FROM public."SOR_Year" WHERE metadata->>'lead_rule_code'=old.rule_code) THEN
  RAISE EXCEPTION 'Shared lead rule is referenced by an annual row'; END IF;
 IF tg_op='DELETE' THEN RETURN old; END IF;
 RETURN new;
END $function$

CREATE OR REPLACE FUNCTION public.sor_shared_lead_validate()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE code text; term jsonb;
BEGIN
 IF EXISTS(SELECT 1 FROM unnest(new.material_codes) AS x(material_code) LEFT JOIN public."SOR_Lead_Profile" p ON p.material_code=x.material_code WHERE p.material_code IS NULL) THEN RAISE EXCEPTION 'Unknown lead material'; END IF;
 IF new.rules->>'schema_version'='3' THEN
  IF new.material_codes<>ARRAY['PIPE']::text[] OR new.review->'reviewer'->>'kind' IS DISTINCT FROM 'ai' THEN RAISE EXCEPTION 'Pipe lead requires AI review'; END IF;
  FOR code IN SELECT jsonb_array_elements_text(new.rules->'source_recipe_codes') LOOP
   IF NOT EXISTS(SELECT 1 FROM public."SOR_Recipie" r WHERE r.recipe_code=code AND r.part_no=4 AND r.lead_applicability='PIPE' AND r.unit=new.rules->>'quantity_unit') THEN RAISE EXCEPTION 'Wrong pipe source or quantity'; END IF;
  END LOOP;
  FOR term IN SELECT jsonb_path_query(new.rules,'$.components.*.**.terms[*]') LOOP
   IF NOT EXISTS(SELECT 1 FROM public."SOR_Recipie" r WHERE r.recipe_code=term->>'recipe_code' AND r.part_no=4 AND
      (r.metadata->>'item_type'='conveyance_matrix_cell' OR
       (new.rules->'source_recipe_codes' ? r.recipe_code AND term->'multiplier'='0.05'::jsonb))) THEN RAISE EXCEPTION 'Invalid pipe transport tariff reference'; END IF;
  END LOOP;
 ELSE
  IF EXISTS(SELECT 1 FROM public.sor_lead_rule_codes(new.rules) AS x(recipe_code) LEFT JOIN public."SOR_Recipie" r ON r.recipe_code=x.recipe_code WHERE r.recipe_code IS NULL OR r.structure<>'MATRIX' OR r.metadata->>'item_type' IS DISTINCT FROM 'conveyance_matrix_cell') THEN RAISE EXCEPTION 'Shared rule must reference existing Conveyance cells'; END IF;
 END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.sor_unit_measure(p_unit text)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
declare u text; parts text[]; size numeric:=1; dimension text;
begin
 u:=lower(trim(p_unit));
 u:=replace(replace(u,'²','2'),'³','3');
 u:=regexp_replace(u,'^per\s+','','i');
 u:=regexp_replace(regexp_replace(u,'\s+',' ','g'),'\.+$','');
 parts:=regexp_match(u,'^([0-9]+(?:\.[0-9]+)?)\s+(.+)$');
 if parts is not null then size:=parts[1]::numeric;u:=regexp_replace(parts[2],'\.+$',''); end if;
 if size<=0 then return null; end if;
 if u in('kg','kgs','kilogram','kilograms') then dimension:='mass';
 elsif u in('tonne','tonnes','metric tonne','one metric tonne','mt') then dimension:='mass';size:=size*1000;
 elsif u in('ltr','liter','litre','liters','litres','l') then dimension:='liquid_volume';
 elsif u in('cum','m3','cu m') then dimension:='solid_volume';
 elsif u in('sqm','sqmt','m2','sq m','sq mtr','sq mtrs') then dimension:='area';
 elsif u in('sqft','sq ft') then dimension:='area';size:=size*0.09290304;
 elsif u in('rm','rmt','m','mtr','mtrs','meter','metre') then dimension:='length';
 elsif u in('km','k.m.') then dimension:='length';size:=size*1000;
 elsif u in('no','nos','each','number') then dimension:='count';
 elsif u in('doz','dozen') then dimension:='count';size:=size*12;
 elsif u in('hour','hours','hr','hrs') then dimension:='hour';
 elsif u in('day','days') then dimension:='day';
 elsif u in('pair','set','job','ls','bag','roll') then dimension:=u;
 else return null; end if;
 return jsonb_build_object('dimension',dimension,'size',size);
end $function$

CREATE OR REPLACE FUNCTION public.sor_unit_rate_factor(p_source_unit text, p_requested_unit text)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
declare source jsonb;requested jsonb;
begin
 if p_source_unit is null then return null; end if;
 if p_requested_unit is null or lower(trim(p_source_unit))=lower(trim(p_requested_unit)) then return 1; end if;
 source:=public.sor_unit_measure(p_source_unit);requested:=public.sor_unit_measure(p_requested_unit);
 if source is null or requested is null or source->>'dimension'<>requested->>'dimension' then return null; end if;
 return (requested->>'size')::numeric/(source->>'size')::numeric;
end $function$

CREATE OR REPLACE FUNCTION public.sor_year_reference_valid()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE r public."SOR_Recipie"; code text;
BEGIN
 SELECT * INTO r FROM public."SOR_Recipie" WHERE recipe_code=new.recipe_code;
 IF new.metadata->>'fixed_rb_item_code'='true' AND new.item_code IS DISTINCT FROM r.item_code THEN
  RAISE EXCEPTION 'R&B yearly Item Code must carry the fixed Recipe Item Code'; END IF;
 code:=new.metadata->>'lead_rule_code';
 IF code IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public."SOR_Lead_Rule" l WHERE l.rule_code=code
  AND l.year=new.year AND l.effective_from=new.effective_from AND r.lead_applicability=ANY(l.material_codes)) THEN
  RAISE EXCEPTION 'Annual lead binding must match the material, year and effective date'; END IF;
 RETURN new;
END $function$

CREATE OR REPLACE FUNCTION public.ssr_annotate_addon_rates(p_ssr_code text, p_year text, p_addon_rates jsonb)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select coalesce(
    jsonb_agg(
      addon.value || jsonb_build_object(
        'rates', jsonb_build_object(
          'materials', public.ssr_annotate_resource_lines(
            p_ssr_code, 'addon:' || (addon.value ->> 'id') || ':materials', p_year, addon.value -> 'rates' -> 'materials'
          ),
          'machinery', public.ssr_annotate_resource_lines(
