CREATE OR REPLACE FUNCTION public.ssr_definition_without_links(x jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
declare result jsonb; k text; v jsonb;
begin
 if jsonb_typeof(x)='object' then
  result:='{}'::jsonb;
  for k,v in select key,value from jsonb_each(x) loop
   if k not in ('resource_identity','sor_ref') then result:=result||jsonb_build_object(k,public.ssr_definition_without_links(v)); end if;
  end loop;
  return result;
 elsif jsonb_typeof(x)='array' then
  select coalesce(jsonb_agg(public.ssr_definition_without_links(value) order by ord),'[]'::jsonb)
  into result from jsonb_array_elements(x) with ordinality a(value,ord);
  return result;
 end if;
 return x;
end $function$

CREATE OR REPLACE FUNCTION public.ssr_identity_from_description_alias(p_ssr_code text, p_analysis_scope text, p_line jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
  v_aliases jsonb;
begin
  select jsonb_agg(identity)
  into v_aliases
  from (
    select distinct case
      when resource_key is not null then public.ssr_curated_resource_identity(resource_key)
      else public.ssr_master_resource_identity(source_table, master_code, rate_component)
    end as identity
    from public.ssr_resource_identity_alias
    where ssr_code = p_ssr_code
      and analysis_scope = p_analysis_scope
      and description_key = public.ssr_normalize_resource_text(p_line ->> 'desc')
  ) candidates;

  if jsonb_array_length(coalesce(v_aliases, '[]'::jsonb)) = 1 then
    return v_aliases -> 0;
  end if;
  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.ssr_identity_from_explicit_alias(p_ssr_code text, p_analysis_scope text, p_line jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
  v_alias public.ssr_resource_identity_alias%rowtype;
begin
  select * into v_alias
  from public.ssr_resource_identity_alias
  where ssr_code = p_ssr_code
    and analysis_scope = p_analysis_scope
    and description_key = public.ssr_normalize_resource_text(p_line ->> 'desc')
    and unit_key = public.ssr_normalize_resource_text(p_line ->> 'unit');

  if not found then return null; end if;
  if v_alias.resource_key is not null then
    return public.ssr_curated_resource_identity(v_alias.resource_key);
  end if;
  return public.ssr_master_resource_identity(
    v_alias.source_table, v_alias.master_code, v_alias.rate_component
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.ssr_identity_from_fixed_master(p_ssr_code text, p_analysis_scope text, p_line jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
  v_identities jsonb;
begin
  select jsonb_agg(identity)
  into v_identities
  from (
    select distinct static_line -> 'resource_identity' as identity
    from public.ssr_static_resource_lines(p_ssr_code, p_analysis_scope) static_line
    where public.ssr_normalize_resource_text(static_line ->> 'desc') = public.ssr_normalize_resource_text(p_line ->> 'desc')
      and public.ssr_normalize_resource_text(static_line ->> 'unit') = public.ssr_normalize_resource_text(p_line ->> 'unit')
      and coalesce(static_line -> 'resource_identity' ->> 'source_table', '') <> ''
      and coalesce(static_line -> 'resource_identity' ->> 'master_code', '') <> ''
  ) candidates;

  if jsonb_array_length(coalesce(v_identities, '[]'::jsonb)) = 1 then
    return v_identities -> 0;
  end if;
  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.ssr_identity_from_sor_ref(p_line jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE ref jsonb:=p_line->'sor_ref';t text;
BEGIN
 IF ref IS NULL OR coalesce(ref->>'code',ref->>'recipe_code',ref->>'resource_code','')='' THEN RETURN NULL; END IF;
 t:=CASE WHEN ref->>'table'='SOR_Recipie' THEN 'SOR_Year' ELSE ref->>'table' END;
 RETURN public.ssr_master_resource_identity(t,coalesce(ref->>'recipe_code',ref->>'resource_code',ref->>'code'),nullif(ref->>'component',''));
END $function$

CREATE OR REPLACE FUNCTION public.ssr_linked_resource_quote(p_recipe_code text, p_analysis_scope text, p_line_index integer, p_year text, p_zone text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
declare revision jsonb;line jsonb;identity jsonb;profile jsonb;quote jsonb;factor numeric;precision integer;
begin
 if p_line_index<0 then raise exception 'Line index must be nonnegative'; end if;
 revision:=public.ssr_resolve_recipe_year(p_recipe_code,p_year);
 if coalesce((revision->>'requires_review')::boolean,false) or revision->>'recipe_code' is null then
  return revision||jsonb_build_object('rate',null);
 end if;
 select l.value into line from public.ssr_static_resource_lines(revision->>'recipe_code',p_analysis_scope)
  with ordinality l(value,ordinality) where l.ordinality=p_line_index+1;
 if line is null then return jsonb_build_object('status','resource_line_missing','rate',null); end if;
 identity:=line->'resource_identity';profile:=identity->'link_review';
 if identity->>'source_table' is distinct from 'SOR_Year' or nullif(identity->>'master_code','') is null then
  return jsonb_build_object('status','resource_link_required','rate',null,'resource_identity',identity);
 end if;
 if profile->>'method'='two_edition_price_tracking' then
  factor:=(profile->>'rate_basis_multiplier')::numeric;
  precision:=(profile->>'rate_rounding_decimals')::integer;
  if profile->>'status' is distinct from 'approved' or factor is null or factor<=0 or precision is null or precision not between 0 and 8 then
   return jsonb_build_object('status','rate_basis_review_required','rate',null);
  end if;
  -- Quote in the verified SOR basis, even if a future edition changes its printed unit.
  -- The stored multiplier converts that reference basis to the SSR use basis.
  quote:=public.sor_resource_quote(identity->>'master_code',p_year,p_zone,coalesce(identity->>'rate_component','rate'),profile->>'reference_sor_unit');
  if quote->>'status'='priced' then
   quote:=quote||jsonb_build_object('sor_rate',quote->'rate','rate',round((quote->>'rate')::numeric*factor,precision),
    'source_unit',quote->>'source_unit','unit',line->>'unit','rate_basis_multiplier',factor,
    'rate_rounding_decimals',precision,'rate_basis_evidence',profile->'two_year_evidence');
  end if;
 else
  quote:=public.sor_resource_quote(identity->>'master_code',p_year,p_zone,coalesce(identity->>'rate_component','rate'),line->>'unit');
 end if;
 return quote||jsonb_build_object('ssr_recipe_code',revision->>'recipe_code','analysis_scope',p_analysis_scope,
  'line_index',p_line_index,'resource_identity',identity);
end $function$

CREATE OR REPLACE FUNCTION public.ssr_master_resource_identity(p_source_table text, p_master_code text, p_rate_component text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
 IF p_source_table='SOR_Year' THEN
  IF NOT EXISTS(SELECT 1 FROM public."SOR_Recipie" WHERE recipe_code=p_master_code) THEN RAISE EXCEPTION 'Unknown or inaccessible SOR Recipe'; END IF;
 ELSIF p_source_table='analysis_resource' THEN
  IF NOT EXISTS(SELECT 1 FROM public.analysis_resource WHERE resource_code=p_master_code) THEN RAISE EXCEPTION 'Unknown or inaccessible analysis resource'; END IF;
 ELSE RAISE EXCEPTION 'Retired resource store: %. Use SOR_Recipie/SOR_Year reviewed links.',p_source_table;
 END IF;
 RETURN jsonb_build_object('version',2,'source_table',p_source_table,'master_code',p_master_code,'recipe_code',CASE WHEN p_source_table='SOR_Year' THEN p_master_code END,'rate_component',p_rate_component,'resource_key',NULL,'resolution',CASE WHEN p_source_table='SOR_Year' THEN 'recipe_code' ELSE 'source_resource' END,'master_resource_resolved',true,'unresolved',false);
END $function$

CREATE OR REPLACE FUNCTION public.ssr_recipe_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
begin
 if TG_OP='DELETE' then raise exception 'Permanent SSR recipes cannot be deleted'; end if;
 if public.ssr_definition_without_links(to_jsonb(new)-array['updated_at','lead_applicability','lead_policy','seigniorage_applicability','description_quantity_policy'])
 is distinct from public.ssr_definition_without_links(to_jsonb(old)-array['updated_at','lead_applicability','lead_policy','seigniorage_applicability','description_quantity_policy'])
 then raise exception 'SSR technical definitions are immutable. Insert a new recipe_code with a reviewed ssr_recipe_link.'; end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.ssr_recipe_link_valid()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE r jsonb; prior public."SSR_Recipe"; source jsonb; source_key text; n integer;
 before_codes jsonb; after_codes jsonb; c text; cardinality_kind text;
BEGIN
 IF TG_OP='DELETE' THEN
  PERFORM pg_advisory_xact_lock(hashtextextended('public.SSR_Recipe.ssr_recipe_link',0));
  IF EXISTS(SELECT 1 FROM public."SSR_Recipe" x WHERE
    public.ssr_recipe_previous(x.ssr_recipe_link) ? old.recipe_code
    OR (x.recipe_code<>old.recipe_code AND public.ssr_recipe_replacements(x.ssr_recipe_link,x.recipe_code) ? old.recipe_code)) THEN

   RAISE EXCEPTION 'Recipe is referenced by a revision predecessor or replacement group'; END IF;
  RETURN old;
 END IF;
 IF TG_OP='UPDATE' AND new.ssr_recipe_link IS NOT DISTINCT FROM old.ssr_recipe_link THEN RETURN new; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('public.SSR_Recipe.ssr_recipe_link',0));
 r:=new.ssr_recipe_link;
 IF r IS NULL THEN
  IF TG_OP='INSERT' AND EXISTS(SELECT 1 FROM public."SSR_Recipe" x WHERE x.source_code=new.source_code) THEN
   RAISE EXCEPTION 'An existing printed SSR code requires a new version with a reviewed ssr_recipe_link';
  END IF;
  RETURN new;
 END IF;
 IF jsonb_typeof(r) IS DISTINCT FROM 'object' OR r->'schema_version' NOT IN ('1'::jsonb,'2'::jsonb)
 OR r->'schema_version' IS NULL THEN RAISE EXCEPTION 'Recipe revision needs reviewed schema 1 or 2'; END IF;
 IF r->>'schema_version'='1' THEN
  IF (SELECT count(*) FROM jsonb_object_keys(r))<>7 OR NOT r ?& ARRAY['schema_version','previous_recipe_code','effective_from_year','change_kind','replacement_mode','reason','review']
   OR jsonb_typeof(r->'previous_recipe_code') IS DISTINCT FROM 'string' THEN RAISE EXCEPTION 'Invalid v1 revision fields'; END IF;
 ELSE
  IF (SELECT count(*) FROM jsonb_object_keys(r))<>8 OR NOT r ?& ARRAY['schema_version','previous_recipe_codes','replacement_recipe_codes','effective_from_year','change_kind','replacement_mode','reason','review']
   OR jsonb_typeof(r->'previous_recipe_codes') IS DISTINCT FROM 'array'
   OR jsonb_typeof(r->'replacement_recipe_codes') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'Invalid v2 revision fields'; END IF;
 END IF;
 before_codes:=public.ssr_recipe_previous(r); after_codes:=public.ssr_recipe_replacements(r,new.recipe_code);
 IF jsonb_array_length(before_codes)=0 OR jsonb_array_length(after_codes)=0
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(before_codes||after_codes) x WHERE jsonb_typeof(x) IS DISTINCT FROM 'string' OR btrim(x#>>'{}')='')
 OR (SELECT count(DISTINCT x) FROM jsonb_array_elements(before_codes) x)<>jsonb_array_length(before_codes)
 OR (SELECT count(DISTINCT x) FROM jsonb_array_elements(after_codes) x)<>jsonb_array_length(after_codes)
 OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(before_codes) x WHERE after_codes ? x)
 OR NOT after_codes ? new.recipe_code THEN RAISE EXCEPTION 'Distinct predecessor and replacement codes required'; END IF;
 IF jsonb_array_length(before_codes)=1 AND jsonb_array_length(after_codes)=1 THEN
  IF coalesce(r->>'change_kind','') NOT IN ('definition_change','reference_change') THEN RAISE EXCEPTION 'Invalid one-to-one revision kind'; END IF;
 ELSE
  cardinality_kind:=CASE WHEN jsonb_array_length(before_codes)=1 THEN 'split_definition'
   WHEN jsonb_array_length(after_codes)=1 THEN 'merged_definition' ELSE NULL END;
  IF cardinality_kind IS NULL OR r->>'change_kind' IS DISTINCT FROM cardinality_kind
   OR r->>'replacement_mode' IS DISTINCT FROM 'review_required' THEN
   RAISE EXCEPTION 'Splits and merges require explicit estimate review'; END IF;
 END IF;
 IF coalesce(r->>'replacement_mode','') NOT IN ('automatic','review_required')
 OR jsonb_typeof(r->'reason') IS DISTINCT FROM 'string' OR btrim(r->>'reason')=''
 OR jsonb_typeof(r->'review') IS DISTINCT FROM 'object'
 OR (SELECT count(*) FROM jsonb_object_keys(r->'review'))<>4
 OR NOT (r->'review') ?& ARRAY['status','reviewer','previous_source','replacement_source']
 OR r->'review'->>'status' IS DISTINCT FROM 'approved'
 OR r->'review'->'reviewer'->>'kind' IS DISTINCT FROM 'ai'
 OR coalesce(r->'review'->'reviewer'->>'model','')='' THEN RAISE EXCEPTION 'Explicit AI revision approval required'; END IF;
 n:=public.sor_fiscal_start(r->>'effective_from_year');
 IF n IS NULL THEN RAISE EXCEPTION 'Revision needs a financial year boundary'; END IF;
 FOREACH source_key IN ARRAY ARRAY['previous_source','replacement_source'] LOOP
  source:=r->'review'->source_key;
  IF jsonb_typeof(source) IS DISTINCT FROM 'object'
  OR (SELECT count(*) FROM jsonb_object_keys(source))<>3
  OR NOT source ?& ARRAY['year','pdf_sha256','pdf_pages']
  OR coalesce(source->>'pdf_sha256','')!~'^[0-9a-f]{64}$'
  OR jsonb_typeof(source->'pdf_pages') IS DISTINCT FROM 'array'
  OR jsonb_array_length(source->'pdf_pages')=0 THEN RAISE EXCEPTION 'Revision source needs PDF hash and pages'; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(source->'pdf_pages') p WHERE jsonb_typeof(p) IS DISTINCT FROM 'number' OR p::text !~ '^[1-9][0-9]*$')
  OR (SELECT count(DISTINCT p) FROM jsonb_array_elements(source->'pdf_pages') p)<>jsonb_array_length(source->'pdf_pages')
  OR public.sor_fiscal_start(source->>'year') IS NULL THEN RAISE EXCEPTION 'Invalid revision source pages/year'; END IF;
 END LOOP;
 IF public.sor_fiscal_start(r->'review'->'previous_source'->>'year')>=n
 OR r->'review'->'replacement_source'->>'year' IS DISTINCT FROM r->>'effective_from_year' THEN RAISE EXCEPTION 'Invalid chronological revision boundary'; END IF;
 FOR c IN SELECT jsonb_array_elements_text(before_codes) LOOP
  SELECT * INTO prior FROM public."SSR_Recipe" WHERE recipe_code=c FOR KEY SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Missing predecessor Recipe'; END IF;
  IF r->>'replacement_mode'='automatic' AND new.unit IS DISTINCT FROM prior.unit THEN RAISE EXCEPTION 'Automatic replacement requires the same quantity basis'; END IF;
 END LOOP;
 RETURN new;
END $function$

CREATE OR REPLACE FUNCTION public.ssr_resolve_recipe_revision(p_recipe_code text, p_year text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE n integer; current_code text; r public."SSR_Recipe"; successor public."SSR_Recipe";
 queue text[]:=ARRAY[p_recipe_code]; path text[]:=ARRAY[]::text[]; blocked text[]:=ARRAY[]::text[];
 selected text[]:=ARRAY[]::text[]; targets text[]; result jsonb;
BEGIN
 n:=public.sor_fiscal_start(p_year);
 IF n IS NULL THEN RAISE EXCEPTION 'Year is required'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public."SSR_Recipe" WHERE recipe_code=p_recipe_code) THEN RAISE EXCEPTION 'Unknown or inaccessible Recipe code'; END IF;
 WHILE cardinality(queue)>0 LOOP
  current_code:=queue[1]; queue:=queue[2:];
  CONTINUE WHEN current_code=ANY(path);
  path:=array_append(path,current_code);
  SELECT * INTO r FROM public."SSR_Recipe" WHERE recipe_code=current_code;
  IF NOT FOUND THEN RAISE EXCEPTION 'Incomplete or inaccessible Recipe lineage'; END IF;
  IF r.ssr_recipe_link IS NOT NULL AND public.sor_fiscal_start(r.ssr_recipe_link->>'effective_from_year')>n THEN
   SELECT array_agg(c ORDER BY c) INTO targets FROM jsonb_array_elements_text(public.ssr_recipe_previous(r.ssr_recipe_link)) c;
   IF r.ssr_recipe_link->>'replacement_mode'='review_required' THEN blocked:=array_append(blocked,current_code); END IF;
   queue:=queue||targets;
  ELSE
   SELECT * INTO successor FROM public."SSR_Recipe" x WHERE public.ssr_recipe_previous(x.ssr_recipe_link) ? current_code LIMIT 1;
   IF FOUND AND public.sor_fiscal_start(successor.ssr_recipe_link->>'effective_from_year')<=n THEN
    SELECT array_agg(c ORDER BY c) INTO targets FROM jsonb_array_elements_text(public.ssr_recipe_replacements(successor.ssr_recipe_link,successor.recipe_code)) c;
    IF successor.ssr_recipe_link->>'replacement_mode'='review_required' THEN blocked:=blocked||targets; END IF;
    queue:=queue||targets;
   ELSE selected:=array_append(selected,current_code);
   END IF;
  END IF;
 END LOOP;
 SELECT coalesce(array_agg(DISTINCT c ORDER BY c),ARRAY[]::text[]) INTO selected FROM unnest(selected) c;
 SELECT coalesce(array_agg(DISTINCT c ORDER BY c),ARRAY[]::text[]) INTO blocked FROM unnest(blocked) c;
 RETURN jsonb_build_object('requested_recipe_code',p_recipe_code,'recipe_code',CASE WHEN cardinality(selected)=1 THEN selected[1] ELSE NULL END,
  'recipe_codes',to_jsonb(selected),'year',p_year,'revision_path',to_jsonb(path),
  'requires_review',cardinality(blocked)>0 OR cardinality(selected)<>1,'review_boundaries',to_jsonb(blocked));
END $function$

CREATE OR REPLACE FUNCTION public.ssr_resolve_recipe_year(p_recipe_code text, p_year text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
declare result jsonb; annual public."SSR_Year"; definition public."SSR_Recipe";
begin
 result:=public.ssr_resolve_recipe_revision(p_recipe_code,p_year);
 if (result->>'requires_review')::boolean then return result||jsonb_build_object('status','recipe_review_required','year_row_code',null); end if;
 select * into definition from public."SSR_Recipe" where recipe_code=result->>'recipe_code';
 result:=result||jsonb_build_object('recipe',to_jsonb(definition));
 select * into annual from public."SSR_Year" where recipe_code=result->>'recipe_code' and year=p_year;
 if not found then return result||jsonb_build_object('status','selected_year_rate_missing','year_row_code',null); end if;
 return result||jsonb_build_object('status',case when annual.base_rate is null then 'rate_unavailable' else 'available' end,
 'year_row_code',annual.year_row_code,'annual',to_jsonb(annual));
end $function$

CREATE OR REPLACE FUNCTION public.ssr_resolve_resource_identity(p_ssr_code text, p_analysis_scope text, p_year text, p_line jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE identity jsonb;
BEGIN
 identity:=public.ssr_identity_from_sor_ref(p_line);IF identity IS NOT NULL THEN RETURN identity; END IF;
 IF p_line->'resource_identity'->>'source_table' IN('SOR_Year','analysis_resource') AND p_line->'resource_identity'->>'master_code' IS NOT NULL THEN RETURN public.ssr_master_resource_identity(p_line->'resource_identity'->>'source_table',p_line->'resource_identity'->>'master_code',p_line->'resource_identity'->>'rate_component'); END IF;
 identity:=public.ssr_identity_from_explicit_alias(p_ssr_code,p_analysis_scope,p_line);IF identity IS NOT NULL THEN RETURN identity; END IF;
 identity:=public.ssr_identity_from_description_alias(p_ssr_code,p_analysis_scope,p_line);IF identity IS NOT NULL THEN RETURN identity; END IF;
 IF p_year IS NOT NULL THEN identity:=public.ssr_identity_from_fixed_master(p_ssr_code,p_analysis_scope,p_line);IF identity IS NOT NULL THEN RETURN identity; END IF; END IF;
 IF coalesce(p_line->'resource_identity'->>'resource_key','') ~ '^ssr:[a-z0-9-]+:[a-z0-9-]+:[a-z0-9-]+-[a-f0-9]{12}$' THEN RETURN public.ssr_curated_resource_identity(p_line->'resource_identity'->>'resource_key'); END IF;
 identity:=public.ssr_identity_from_resource_key(p_ssr_code,p_analysis_scope,p_line);IF identity IS NOT NULL THEN RETURN identity; END IF;
 RETURN public.ssr_description_unit_identity(p_line);
END $function$
